@@ -0,0 +1,99 @@
+// KS-2174 part 2 (the two seeder hint arms): the demo seeder's two arms that carry a `hint` -- the warn arm `Demo user NOT seeded (no password supplied) ...` and the info arm
+// `Demo user seeding skipped ...` in userRepo.ts -- put the account's raw email address in their meta (`email: account.email`). The change replaces it with `userId: account.id`,
+// the same swap part 1 (PR 2216) made at the other five seeder lines. The `hint` strings are unchanged.
+//
+// Each cell drives the REAL `seedDemoUsers` with no password supplied (the db, the logger, the PII crypto and the subject-DEK service are replaced; the harness is COPIED from part 1's
+// ks2174-demo-seeder-log-lines-carry-no-raw-email.test.ts, because that file belongs to PR 2216 and cannot be edited here) into ONE state that reaches one arm, then reads every recorded
+// call of that arm's message. Three assertions per cell, all must hold: the arm WAS reached (a cell that never reaches its line proves nothing), no meta value of any call holds an
+// email-shaped string, and the calls name both no-password accounts by id (`userId`), so the change cannot be "drop the field". RED at the unchanged product, green with the change.
+// C1 is a control on the instrument: the oracle must flag a planted raw address and must not flag a `userId`-only meta.
+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+vi.mock('@secuura/shared', async (importOriginal) => {
+  const actual = await importOriginal<Record<string, unknown>>();
+  return {
+    ...actual,
+    encryptField: async (v: string) => v,
+    decryptField: async (v: string) => v,
+    encryptFieldWithDek: async (v: string) => v,
+    decryptFieldWithDek: async (v: string) => v,
+    isSubjectDekCiphertext: () => false,
+    isEncryptedPii: () => false,
+    lookupHash: (v: string) => `hash:${v}`,
+  };
+});
+vi.mock('../services/subjectDeks', () => ({
+  subjectDeks: { getDek: async () => 'test-dek', getOrCreateDek: async () => 'test-dek' },
+}));
+
+const logCalls: Array<{ level: string; msg: string; meta: Record<string, unknown> }> = [];
+vi.mock('../utils/logger', () => ({
+  logger: {
+    info: (msg: string, meta: Record<string, unknown>) => { logCalls.push({ level: 'info', msg, meta }); },
+    warn: (msg: string, meta: Record<string, unknown>) => { logCalls.push({ level: 'warn', msg, meta }); },
+    error: (msg: string, meta: Record<string, unknown>) => { logCalls.push({ level: 'error', msg, meta }); },
+    debug: () => {},
+  },
+}));
+
+// The state the db mock presents. Reset by every cell.
+const world = { anyIdRow: false, emailExists: false, emailRow: null as Record<string, unknown> | null };
+vi.mock('../db', () => ({
+  query: vi.fn(async (sql: string, params: unknown[] = []) => {
+    const s = String(sql);
+    if (/EXISTS\s*\(\s*SELECT 1 FROM auth_find_user_by_email_hash/i.test(s)) return { rows: [{ exists: world.emailExists }], rowCount: 1 };
+    if (/auth_find_user_by_email_hash/i.test(s)) return world.emailRow ? { rows: [world.emailRow], rowCount: 1 } : { rows: [], rowCount: 0 };
+    if (/select/i.test(s) && /from\s+users/i.test(s) && world.anyIdRow) {
+      const id = String(params[0] ?? '');
+      return { rows: [{ id, email: 'stale.identity@example.invalid', status: 'active', role: 'user' }], rowCount: 1 };
+    }
+    return { rows: [], rowCount: 0 };
+  }),
+}));
+
+const ADDRESS = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+/;
+const hasAddress = (meta: unknown) => ADDRESS.test(JSON.stringify(meta ?? {}));
+
+// The two accounts the seeder skips when no password is supplied (the KS-949 KS-966 F2 cells name the same two ids).
+const ADMIN_ID = 'a0000000-0000-4000-8000-000000000020';
+const PLATFORM_ADMIN_ID = 'a0000000-0000-4000-8000-000000000060';
+
+async function runSeed() {
+  const saved = { ...process.env };
+  Object.assign(process.env, { NODE_ENV: 'development', ALLOW_DEFAULT_SEED_PASSWORDS: 'true' });
+  delete process.env.DEMO_SECUURA_PASSWORD;
+  delete process.env.ADMIN_USER_PASSWORD;
+  vi.resetModules();
+  logCalls.length = 0;
+  const { seedDemoUsers } = await import('../repositories/userRepo');
+  await seedDemoUsers(async (pw: string) => `hashed:${pw}`);
+  process.env = saved;
+}
+
+const ARMS: Array<{ line: number; level: string; msg: string; state: string; setup: () => void }> = [
+  { line: 1764, level: 'warn', msg: 'Demo user NOT seeded', state: 'no password, an id row', setup: () => { world.anyIdRow = true; } },
+  { line: 1764, level: 'warn', msg: 'Demo user NOT seeded', state: 'no password, a distinct email row',
+    setup: () => { world.emailExists = true; world.emailRow = { id: 'ks2174-part2-distinct-row', email: 'distinct.row@example.invalid', role: 'user', status: 'active', email_verified: true }; } },
+  { line: 1773, level: 'info', msg: 'Demo user seeding skipped', state: 'no password, nothing to remediate', setup: () => {} },
+];
+
+describe('KS-2174 part 2: the demo seeder hint arms carry no raw email address', () => {
+  beforeEach(() => { world.anyIdRow = false; world.emailExists = false; world.emailRow = null; vi.clearAllMocks(); });
+  afterEach(() => vi.resetModules());
+
+  it.each(ARMS)('RED KS-2174 part 2 userRepo.ts:$line "$msg" ($state): reached, no meta value holds an email address, both accounts named by id', async (arm) => {
+    arm.setup();
+    await runSeed();
+    // The message also names two other info calls (userRepo.ts 1333 and 1337, no meta, the not-seeding-at-all branch); 'no password supplied' selects the two hint arms only.
+    const calls = logCalls.filter((c) => c.level === arm.level && c.msg.startsWith(arm.msg) && c.msg.includes('no password supplied'));
+    expect([arm.line, arm.state, calls.length > 0]).toEqual([arm.line, arm.state, true]);
+    const leaking = calls.filter((c) => hasAddress(c.meta));
+    expect([arm.line, arm.state, leaking.length, leaking[0] ? Object.keys(leaking[0].meta) : []]).toEqual([arm.line, arm.state, 0, []]);
+    const ids = calls.map((c) => c.meta['userId']);
+    expect([arm.line, arm.state, ids]).toEqual([arm.line, arm.state, expect.arrayContaining([ADMIN_ID, PLATFORM_ADMIN_ID])]);
+  });
+
+  it('control KS-2174 part 2 C1: the oracle flags a planted raw address and passes a userId-only meta', () => {
+    expect([hasAddress({ email: 'planted.person@example.invalid' }), hasAddress({ userId: ADMIN_ID, hint: 'set ADMIN_USER_PASSWORD to seed this account instead' }), hasAddress({ remediatedById: true })]).toEqual([true, false, false]);
+  });
+});

