-    expect(hintFor('admin@secuura.com')).not.toEqual(hintFor(PLATFORM_ADMIN));
+    // KS-2174 part 2: keyed by account id (the arms no longer log the address).
+    expect(hintFor(ADMIN_ID)).not.toEqual(hintFor(PLATFORM_ADMIN_ID));
